import {course,units,unitById,unitForWeek,evaluation,rubric,milestones} from './course.js';
import {resources,resourceById,kindNames,resourceHref} from './resources.js';
import {lessons} from './lessons.js';
import {classSlides} from './class-content.js';
export {classSlides} from './class-content.js';
import {glossary,examples} from './glossary.js';
import {sessions,getSession} from './encounters.js';
import {weeklyPath,sessionWork,projectFieldForWeek} from './learning-path.js';
import {unitActivities,writingStages} from './activities.js';
import {unitCorpusIds,unitSequence,evidenceSources,sessionMaterials,newEvidenceSource} from './workflow.js';
import {steps} from './navigation.js';
import {workStatus,hasWork} from './state.js';
import {esc,fieldLabels,sectionTitle,evidenceHtml,relationDiagram} from './export.js';

export const icon=`<svg viewBox="0 0 24 24" class="icon" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>`;
export const button=(action,label,extra='',primary=false)=>`<button type="button" data-action="${action}" ${extra} class="button${primary?' primary':''}">${label}</button>`;
const link=(href,label,primary=false,extra='')=>`<a class="button${primary?' primary':''}" href="${esc(href)}" ${extra}>${label}${icon}</a>`;
const status=(state,key)=>`<span class="work-state" data-work-status="${esc(key)}">${esc(workStatus(state,key))}</span>`;
export function prose(text){return String(text).split(/(\[\[[a-z-]+(?:\|[^\]]+)?\]\])/g).map(part=>{const match=part.match(/^\[\[([a-z-]+)(?:\|([^\]]+))?\]\]$/);return match&&glossary[match[1]]?`<button type="button" class="concept" data-concept="${match[1]}">${esc(match[2]||glossary[match[1]].term)}</button>`:esc(part);}).join('');}
export function field(state,key,name,label=fieldLabels[name],help='',rows=4,editable=true){const id=`${key}-${name}`,value=state.notes[key]?.[name]||'';return `<div class="field"><label for="${id}">${esc(label)}</label>${help?`<p class="field-help" id="${id}-help">${esc(help)}</p>`:''}<textarea id="${id}" name="${name}" data-note="${key}" data-field="${name}" rows="${rows}" maxlength="60000" ${help?`aria-describedby="${id}-help"`:''} ${editable?'':'readonly'}>${esc(value)}</textarea><p class="field-error" id="${id}-error"></p></div>`;}
export function resourceCard(r,compact=false){
 const href=resourceHref(r),external=href?.startsWith('https:');
 const label=href?.startsWith('#')?'Abrir material del curso':r.format==='pdf'?`Abrir PDF · página ${r.startPage}`:r.format==='video'?'Ver video y transcripción':'Abrir texto original';
 return `<article class="resource${compact?' compact':''}" data-resource="${r.id}"><div class="resource-type">${esc(kindNames[r.kind])}<span>${esc(r.access)}</span></div><h3>${esc(r.title)}</h3><p class="resource-author">${esc(r.author)} · ${esc(r.year)}</p>${compact?'':`<p>${esc(r.description)}</p>`}<p class="selection"><strong>Trabajar con:</strong> ${esc(r.selection)}</p>${href?`<a class="source-link" href="${esc(href)}" ${external?'target="_blank" rel="noopener noreferrer"':''}>${esc(label)}${icon}<span class="sr-only">: ${esc(r.title)}${external?' (otra pestaña)':''}</span></a>`:`<p class="caption">${r.url?'Acceso pendiente de comprobación; no se ofrece como lectura disponible.':'Referencia para consulta en ejemplar o biblioteca; no hay descarga abierta en esta página.'}</p>`}</article>`;
}
const minimums=u=>`<details class="coverage"><summary>Contenidos del programa y evidencia esperada</summary><ul>${u.minimums.map(([id,name])=>`<li><span class="mono">${id}</span> ${esc(name)}</li>`).join('')}</ul><p>${esc(u.product)}</p></details>`;
export function sidebar(route,state){return `<a class="side-intro" href="#inicio">Recorrido del curso</a><nav aria-label="Unidades">${units.map(u=>`<a href="#unidad/${u.id}/situar" ${route.unit===u.id?'aria-current="page"':''}><span class="unit-index">${u.id}</span><span>${esc(u.title)}<small>Semanas ${u.weeks[0]}–${u.weeks[1]}</small></span></a>`).join('')}</nav><div class="side-foot"><a href="#glosario">Glosario situado</a><p>Observar.<br>Interpretar.<br>Revisar.</p><p class="caption">El progreso registra trabajo, no una calificación.</p></div>`;}
function schedule(){return `<section class="schedule" id="programacion"><h2>Programación por encuentros</h2><p>Las semanas distribuyen el trabajo de las seis unidades: no son diagnósticos nuevos. Solo la semana 1 recoge tu lectura inicial y su contraste, sin calificación. Después construyes una ficha por unidad y un expediente que avanza en cuatro hitos.</p><p>Abre una semana y entra en sus clases para consultar la preparación, los materiales y las consignas. Las clases y las unidades conducen a las mismas fichas; no son un plan para casa y otro para el aula.</p>${weeklyPath.map((path,i)=>{const week=i+1,u=unitForWeek(week),projectField=projectFieldForWeek(week);return `<details class="week-row"><summary><span class="mono">Semana ${week}</span><span>${esc(path.title)}<small class="meeting-meta">Unidad ${u.id} · ${esc(u.title)}</small></span></summary><div class="week-meetings">${[1,2].map(n=>meetingLink(getSession(week,n))).join('')}</div><p><strong>Avance de esta semana:</strong> ${esc(path.advance)}</p><div class="actions">${link(`#unidad/${u.id}/situar`,`Ver unidad ${u.id}`)}${week===1?link('#cuaderno','Ver mi diagnóstico'):week<15?link(`#unidad/${u.id}/argumentar`,`Abrir mi ficha ${u.id}`):''}${projectField?link('#proyecto',`Trabajar en el hito ${path.milestone}`,false,`data-project-field="${projectField}"`):''}</div></details>`;}).join('')}</section>`;}
function home(state){return `<section class="course-opening"><div><h1>Análisis<br>del discurso</h1><p class="opening-subtitle">Perspectivas críticas y laboratorio de análisis</p><p class="lead">Pasar de una observación a una interpretación que podamos sostener, contrastar y revisar.</p><div class="actions">${hasWork(state)&&state.lastLocation!=='#inicio'?link(state.lastLocation,'Continuar mi trabajo',true)+link('#semana/1/1','Volver al diagnóstico'):link('#semana/1/1','Comenzar con el diagnóstico',true)+link('#cuaderno','Conocer mi cuaderno')}</div><p class="caption">Formación docente · Nivel avanzado · ${esc(course.institution)}</p></div><div class="method-rail" aria-label="Operaciones del laboratorio"><h2>Una interpretación<br>necesita evidencia.</h2><ol><li><span>Situar</span>Quién, dónde y bajo qué condiciones.</li><li><span>Observar</span>Un segmento que otro lector pueda localizar.</li><li><span>Analizar</span>Registrar fragmentos, categorías y explicaciones.</li><li><span>Argumentar</span>La relación entre el dato y la conclusión.</li><li><span>Revisar</span>La alternativa que pone a prueba la lectura.</li></ol></div></section><section class="course-intent"><h2>El problema guía el método</h2><p>No se espera coincidir con una interpretación del docente. Se espera describir con precisión, documentar el contexto, justificar categorías y responder a lecturas alternativas. La perspectiva crítica atraviesa oralidad, escritura, voces y prácticas sociales.</p></section><section class="unit-list"><h2>Seis unidades, un expediente</h2>${units.map(u=>`<article><span class="unit-index">${u.id}</span><div><h3><a href="#unidad/${u.id}/situar">${esc(u.title)}</a></h3><p>${esc(u.question)}</p><small>${esc(u.official)} · Semanas ${u.weeks[0]}–${u.weeks[1]}</small></div><div class="unit-product">${status(state,`ficha-${u.id}`)}<p>${esc(u.product)}</p><a href="#unidad/${u.id}/situar" class="text-link">Entrar a la unidad ${icon}</a></div></article>`).join('')}</section>${schedule()}<section class="evaluation" id="evaluacion"><h2>Cómo se valora el trabajo</h2><p>96 horas: 32 de docencia, 16 de práctica y 48 autónomas. Completa las seis fichas y selecciona dos para una revisión comentada más profunda, según la orientación del docente. Conserva en ellas la primera interpretación, la versión revisada y la explicación del cambio; los botones del cuaderno no sustituyen esa devolución. Selecciona para el expediente las evidencias que respondan a su pregunta.</p><div class="table-wrap"><table><caption>Componentes institucionales</caption><thead><tr><th>Componente</th><th>Evidencia</th><th>Peso</th></tr></thead><tbody>${evaluation.map(([title,weight,evidence])=>`<tr><th>${esc(title)}</th><td>${esc(evidence)}</td><td>${weight}%</td></tr>`).join('')}</tbody></table></div><p>El progreso del navegador indica trabajo iniciado o revisado. No calcula una nota ni decide si una interpretación social es verdadera.</p>${link('#proyecto','Abrir el expediente final')}</section>`;}
function meetingLink(s,index=null){const m=sessionMaterials(s);return `<a href="#semana/${s.week}/${s.encounter}" data-encounter="${s.id}"><span class="meeting-meta">${index===null?'':`Clase ${index+1} · `}Semana ${s.week} · Encuentro ${s.encounter} · ${s.duration} minutos</span><strong>${esc(s.title)}</strong><span><b>Documento de análisis:</b> ${m.corpus.length?esc(m.corpus.map(id=>resourceById[id].title).join('; ')):s.week===8?'Caso nuevo indicado por el docente':'Tu expediente y sus documentos'}</span>${m.readings.length?`<span class="caption"><b>Lectura de apoyo:</b> ${esc(m.readings.map(id=>resourceById[id].title).join('; '))}</span>`:''}<span><b>Avance:</b> ${esc(s.product)}</span>${icon}</a>`;}
function unitMeetings(u,open=false){return `<details class="unit-meetings" ${open?'open':''}><summary>Encuentros en orden · Unidad ${u.id}</summary><p>Sigue las clases en este orden. Cada una retoma el resultado anterior y añade la operación indicada en «Avance». El documento y las lecturas son materiales de la clase, no actividades separadas. Conserva la misma ficha ${u.id} entre encuentros.${u.id===6?' Las últimas cuatro clases trabajan en el expediente final.':''}</p>${u.id===1?`<details class="prior-diagnosis"><summary>Diagnóstico previo · Semana 1</summary><p>Está guardado aparte de la ficha oral. No necesitas repetirlo al comenzar esta unidad.</p>${link('#semana/1/1','Consultar el diagnóstico inicial')}${link('#semana/1/2','Consultar su contraste')}</details>`:''}<div class="week-meetings unit-sequence">${unitSequence(u.id).map((s,i)=>meetingLink(s,i)).join('')}</div></details>`;}
function readingResources(u){const all=u.resources.filter(id=>!id.startsWith('guia')).map(id=>resourceById[id]),support=r=>!resourceHref(r)||r.access.includes('complementario')||r.selection.includes('apoyo docente');return `<h2>Materiales para el trabajo</h2><p class="caption">Empieza por la guía de esta página. Para cada clase, prepara el material indicado en su encuentro; no toda esta lista a la vez.</p>${all.filter(r=>!support(r)).map(r=>resourceCard(r,true)).join('')}<details class="teacher-references"><summary>Referencias y apoyos para ampliar</summary><p class="caption">Consúltalos cuando el docente indique un recorte y su forma de acceso. Los ejemplares personales no son descargas abiertas.</p>${all.filter(support).map(r=>resourceCard(r,true)).join('')}</details>`;}
function unitHeader(u,step,state,origin){return `<div class="page-heading"><h1>${esc(u.title)}</h1><p class="lead">${esc(u.question)}</p><p class="caption">Unidad ${u.id} · ${esc(u.official)} · Semanas ${u.weeks[0]}–${u.weeks[1]}</p>${origin?.unit===u.id&&step!=='situar'?`<div class="actions">${link(`#semana/${origin.week}/${origin.encounter}`,`Volver al encuentro: ${esc(origin.title)}`,true)}</div>`:''}</div><p class="caption workspace-help">Espacios de la misma ficha: el orden de clases está en «Unidad y encuentros». Abre los demás espacios cuando la consigna de clase lo indique.</p><nav class="step-nav" aria-label="Espacios de la ficha">${steps.map(([id,title])=>`<a href="#unidad/${u.id}/${id}" ${id===step?'aria-current="step"':''}>${title}</a>`).join('')}</nav>`;}
function evidenceList(state,unit,editable=false,insert=false){const entries=state.evidence.filter(e=>!unit||e.unit===unit);return entries.length?entries.map(e=>`<div class="evidence-item">${evidenceHtml(e)}<div class="actions">${insert?button('insert-evidence','Insertar registro y fuente',`data-id="${esc(e.id)}"`):''}${editable?button('edit-evidence','Editar evidencia',`data-id="${esc(e.id)}"`)+button('delete-evidence','Eliminar evidencia',`data-id="${esc(e.id)}"`):''}</div></div>`).join(''):'<p class="empty">Registra una evidencia con fuente y localizador. Podrás consultarla al escribir y mostrarla en los anexos que elijas.</p>';}
export function evidenceForm(unit,entry=null,editable=true){const sources=evidenceSources(unit,entry),base=sources[0],e=entry||(base?{resource:base.id,source:`${base.author} · ${base.title} · ${base.year}`}:{ }),editing=!!e.id,input=(name,label,required=false,help='')=>`<div class="field"><label for="e-${name}">${label}${required?' <span class="required">(necesario)</span>':''}</label>${help?`<p class="field-help">${help}</p>`:''}<${['source','locator','category'].includes(name)?'input':'textarea'} id="e-${name}" name="${name}" ${required?'required':''} maxlength="10000" ${editable?'':'disabled'} ${['source','locator','category'].includes(name)?`value="${esc(e[name]||'')}">`:`rows="3">${esc(e[name]||'')}</textarea>`}</div>`;
 return `<form id="evidence-form" data-unit="${unit}"><h2>${editing?'Editar evidencia':'Registrar una evidencia'}</h2><p class="caption">Una entrada corresponde a un segmento, una marca o una comparación identificable. Completa primero fuente, localizador y fragmento o descripción; después puedes editarla para ampliar el análisis. Al añadir otra entrada se conservan el documento y la fuente de esta unidad; los demás campos empiezan vacíos. La preparación se conserva al navegar, pero solo aparece en la lista al pulsar «${editing?'Guardar cambios':'Añadir evidencia'}».</p><input type="hidden" name="id" value="${esc(e.id||'')}"><div class="form-row"><div class="field"><label for="e-resource">Documento de trabajo</label><p class="field-help">Elige solo el documento que estás analizando. Puedes usar el corpus indicado en clase o «Otro documento de mi corpus» para un material propio, una adaptación o un episodio de taller. No debes analizar todos los títulos: los libros y artículos de apoyo se citan en «Categoría y marco utilizado».</p><select id="e-resource" name="resource" ${editable?'':'disabled'}><option value="">Otro documento de mi corpus</option>${sources.map(r=>`<option value="${esc(r.id)}" ${e.resource===r.id?'selected':''}>${r.legacy?'Documento de un registro anterior: ':r.access?.includes('complementario')?'Ampliación opcional: ':'Corpus de la unidad: '}${esc(r.title)}</option>`).join('')}</select>${sources.some(r=>r.legacy)?'<p class="caption">Se conserva el documento de tu registro anterior. No necesitas sustituirlo para consultar o editar lo que ya escribiste.</p>':''}</div><div class="field"><label for="e-mode">Tipo de registro</label><p class="field-help">«Cita literal» reproduce palabras exactas. «Descripción» registra lo que observas, por ejemplo una pausa, un gesto o una disposición visual.</p><select name="mode" id="e-mode" ${editable?'':'disabled'}><option value="descripcion" ${e.mode!=='cita'?'selected':''}>Descripción de un recurso</option><option value="cita" ${e.mode==='cita'?'selected':''}>Cita literal</option></select></div></div>${input('source','Fuente: autor, título y versión',true,'Revisa que la referencia corresponda al documento que usaste. Si es una elaboración tuya, indícalo y dale un título; no la atribuyas al autor del original.')}${input('locator','Localizador: página, artículo, párrafo o intervalo',true,'Escribe una ubicación que otro lector pueda encontrar: «PDF p. 2, art. 3», «00:39–00:52» o el párrafo identificado en tu adaptación.')}${input('observation','Fragmento o descripción observable',true,'Copia las palabras sin modificarlas si citas. Si describes, señala exactamente qué se ve o escucha y dónde; reserva la explicación de su función para «Interpretación».')}${input('category','Categoría y marco utilizado',false,'Nombra la herramienta analítica y el autor o enfoque que empleas. Explica su pertinencia en el argumento; acumular etiquetas no reemplaza analizar.')}${input('context','Contexto documentado y su fuente',false,'Anota el dato pertinente, su fuente y localizador. Distingue la situación registrada de una hipótesis pendiente de comprobar; la fuente de contexto puede ser distinta de la del fragmento.')}${input('interpretation','Interpretación que permite sostener',false,'Explica qué relación permite proponer la marca observada, bajo qué condiciones y con qué límite. No atribuyas una intención o un efecto solo por la presencia de una forma.')}${input('alternative','Otra explicación o dato que falta',false,'Formula otra explicación de la misma marca o identifica el dato que permitiría contrastarla. No necesitas inventar una respuesta concluyente si falta evidencia.')}<div class="actions"><button class="button primary" type="submit" ${editable?'':'disabled'}>${editing?'Guardar cambios':'Añadir evidencia'}${icon}</button>${button('cancel-evidence',editing?'Cancelar edición':'Vaciar preparación')}</div><p class="caption">${editing?'Cancelar edición deja intacta la entrada registrada y descarta esta preparación de cambios.':'Vaciar preparación borra lo escrito en este formulario; no elimina las evidencias que ya añadiste.'}</p><p id="evidence-error" class="field-error" role="alert"></p></form>`;
}
function activityInstructions(u){const a=unitActivities[u.id];return `<section class="activity-instructions"><h2>Trabajo acumulado de la ficha ${u.id}</h2><p><strong>Material de trabajo:</strong> ${esc(a.material)}</p><p>Estas consignas reúnen el resultado de los encuentros de la unidad. Sigue la agenda de la clase actual y completa aquí solo lo que corresponda a ese avance. Retoma los registros existentes; no empieces de nuevo al abrir este espacio. Usa esta lista para comprobar qué falta en la ficha.</p><ol>${a.steps.map(([title,text])=>`<li><h3>${esc(title)}</h3><p>${esc(text)}</p></li>`).join('')}</ol><p><strong>Resultado que debes conservar:</strong> ${esc(a.product)}</p></section>`;}
function unitPage(route,state,editable,origin){const u=unitById[route.unit],a=unitActivities[u.id],key=`ficha-${u.id}`,header=unitHeader(u,route.step,state,origin);let content='';
 if(route.step==='situar')content=`<div class="reading"><p class="lead">${esc(u.intro)}</p><h2>El trabajo de esta unidad</h2><p>${esc(u.product)}</p>${unitMeetings(u,true)}<h2>Preguntas para el corpus</h2><ul>${u.prompts.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${minimums(u)}<h2>Lentes de análisis</h2><div class="concept-links">${u.concepts.map(id=>`<button class="concept" data-concept="${id}">${esc(glossary[id].term)}</button>`).join('')}</div><p class="caption">Antes de clase, lee la guía y prepara el material del encuentro. Durante la clase, sigue su agenda y registra evidencias. Después, desarrolla o revisa la misma ficha. La barra abre espacios de la misma ficha: «Guía de lectura» explica herramientas; «Registrar evidencias» conserva segmentos; «Escribir argumento» reúne la interpretación; «Revisar ficha» guarda el contraste. El orden de actividades corresponde a los encuentros de arriba. Las preguntas de esta página orientan la lectura; no son entregas adicionales.</p>${link(`#unidad/${u.id}/observar`,'Consultar la guía de lectura',true)}</div>`;
 if(route.step==='observar')content=`<div class="reading-layout"><article class="reading lesson"><p class="caption">Lee esta guía para preparar las operaciones de la unidad. Sus ejemplos y preguntas explican conceptos; la actividad que debes conservar en tu ficha está en «Registrar evidencias». No necesitas producir una entrega por cada párrafo de la guía.</p>${lessons[u.id].map(([title,text])=>`<section><h2>${esc(title)}</h2><p>${prose(text)}</p></section>`).join('')}<p class="caption">Guía propia del curso. Las referencias y recortes disponibles se identifican al lado y en la biblioteca.</p>${link(`#unidad/${u.id}/situar`,'Volver al orden de encuentros',true)}${link(`#unidad/${u.id}/analizar`,'Consultar el registro de la ficha')}</article><aside class="reading-resources" aria-label="Lecturas de esta unidad">${readingResources(u)}</aside></div>`;
 if(route.step==='analizar')content=`<div class="analysis-desk"><section class="document-desk">${activityInstructions(u)}${unitCorpusIds[u.id].map(id=>resourceCard(resourceById[id],true)).join('')}<h2>Evidencias de la unidad</h2>${evidenceList(state,u.id,editable)}${link(`#unidad/${u.id}/argumentar`,`Escribir el argumento de la ficha ${u.id}`,true)}</section><section class="register-desk">${evidenceForm(u.id,newEvidenceSource(u.id,state.evidence),editable)}</section></div>`;
 if(route.step==='argumentar')content=`<div class="writing-desk"><section><h2>Escribir la ficha ${u.id} con mis evidencias</h2><p class="caption">${esc(writingStages[u.id])}</p><p>Retoma los registros de «Registrar evidencias» y responde a tu pregunta. Las evidencias permiten sostener la lectura; no se convierten por sí solas en un argumento. ${esc(a.product)}</p>${link(`#unidad/${u.id}/analizar`,'Consultar los pasos de la actividad')}${field(state,key,'question','Pregunta de la ficha',a.questionHelp,3,editable)}${field(state,key,'argument','Mi argumento',a.argumentHelp,12,editable)}<p class="caption" data-word-count="${key}-argument"></p><p class="caption">Este contador corresponde solo a «Mi argumento». La ficha no tiene la extensión del expediente final. «Insertar registro y fuente» añade al texto la cita o descripción con su referencia, en el cursor o en lugar del texto seleccionado; debes explicar después su relación con tu interpretación.</p><details class="method-check"><summary>Comprobar mi interpretación antes de revisarla</summary><ul>${u.alerts.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>${link(`#unidad/${u.id}/revisar`,'Contrastar y escribir mi revisión',true)}</section><aside class="desk-evidence"><h2>Mis evidencias</h2>${evidenceList(state,u.id,false,true)}${link(`#unidad/${u.id}/analizar`,state.evidence.some(e=>e.unit===u.id)?'Volver al registro de evidencias':'Registrar mi primera evidencia')}</aside></div>`;
 if(route.step==='revisar')content=`<div class="reading"><h2>Contrastar y conservar las dos versiones</h2><ol><li>Vuelve a «Mi argumento» y lee tu primera interpretación. Déjala allí; escribe la nueva versión en «Interpretación revisada» para poder compararlas.</li><li>Contrasta con una objeción de otro lector, un dato nuevo o una explicación alternativa. ${esc(a.reviewFocus)}</li><li>Escribe la interpretación que ahora puedes sostener. Puedes corregirla, restringirla o conservarla con una justificación mejor.</li><li>Explica el cambio en el campo siguiente. Cuando completes argumento, versión revisada y explicación, pulsa «Registrar revisión».</li></ol><p class="caption">Los textos se guardan al escribir. El botón marca la ficha como revisada; no la envía al docente ni asigna una calificación. Para conservar otras versiones, guarda un respaldo JSON antes de reemplazar un texto.</p>${link(`#unidad/${u.id}/argumentar`,'Volver a mi primera interpretación')}${status(state,key)}${field(state,key,'revision','Interpretación revisada','Responde de nuevo a la pregunta de la ficha con el contraste realizado. Identifica la evidencia que sostiene lo que corriges, restringes o mantienes.',6,editable)}${field(state,key,'revisionReason','Qué cambió y por qué','Explica: antes sostenía…; la objeción o el dato fue…; ahora sostengo…; sigue faltando…. Puedes mantener la lectura, pero debes justificar por qué resiste el contraste.',5,editable)}<div class="actions">${button('review','Registrar revisión',`data-key="${key}" ${editable?'':'disabled'}`,true)}${link('#proyecto','Consultar mi ficha en el expediente',false,`data-project-pane="notes" data-project-unit="${u.id}"`)}${u.id<units.length?link(`#unidad/${u.id+1}/situar`,'Ver la siguiente unidad'):link('#proyecto','Continuar el cierre del expediente')}</div><p id="review-error" class="field-error" role="alert"></p>${minimums(u)}</div>`;
 return header+(['analizar','argumentar','revisar'].includes(route.step)?'<p class="caption work-help">Tus notas y preparaciones se guardan automáticamente en este navegador. Añadir evidencia la incorpora al registro; registrar una revisión no equivale a enviar una entrega.</p>':'')+content;
}
export function filterResources({query='',unit='',kind='',scope=''}={}){const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const q=normalize(query);return resources.filter(r=>(!unit||r.units.includes(+unit))&&(!kind||r.kind===kind)&&(!scope||(scope==='docente'?r.access==='Consulta docente':scope==='operativo'?!!resourceHref(r):true))&&normalize([r.title,r.author,r.description].join(' ')).includes(q));}
export const libraryResults=filters=>{const found=filterResources(filters);return `<p class="caption" role="status">${found.length} ${found.length===1?"recurso":"recursos"} en esta selección.</p>${found.length?found.map(r=>resourceCard(r)).join(''):'<p class="empty">No hay coincidencias. Cambia la unidad, la función o las palabras de búsqueda.</p>'}`;};
function library(){return `<div class="page-heading"><h1>Corpus y lecturas</h1><p class="lead">El documento es el objeto de análisis. La teoría permite formular preguntas. La guía ayuda a realizar la operación.</p></div><form id="library-filters" class="library-filters"><div class="field"><label for="library-query">Buscar por texto o autor</label><input id="library-query" name="query" type="search"></div><div class="field"><label for="library-unit">Unidad</label><select id="library-unit" name="unit"><option value="">Todas las unidades</option>${units.map(u=>`<option value="${u.id}">${u.id}. ${esc(u.title)}</option>`).join('')}</select></div><div class="field"><label for="library-kind">Función</label><select id="library-kind" name="kind"><option value="">Todas las funciones</option>${Object.entries(kindNames).map(([id,title])=>`<option value="${id}">${title}</option>`).join('')}</select></div><div class="field"><label for="library-scope">Disponibilidad</label><select id="library-scope" name="scope"><option value="">Todas las referencias</option><option value="operativo" selected>Material integrado o enlazado</option><option value="docente">Consulta docente</option></select></div></form><p class="caption">Los libros personales se identifican como consulta docente; su disponibilidad no constituye acceso abierto. Cada actividad indica el recorte y ofrece una ruta operativa.</p><div id="library-results" class="resource-list">${libraryResults({scope:"operativo"})}</div>`;}
function project(state,editable,origin=null){
 const groups=[
  [['title','Título del expediente','Nombra el problema y el corpus que estudias; puedes ajustar el título después de analizar.',2],['student','Nombre para la entrega','Este nombre aparece en la portada del PDF.',2],['question','Pregunta de investigación','Formula una relación que puedas investigar en 2–4 documentos o episodios. Por ejemplo, pregunta cómo se representa una decisión en un tramo identificado; evita dar por demostrada una intención. Puedes partir de una ficha, pero delimita una sola pregunta para todo el expediente.',3],['corpus','Corpus y criterios de selección','Lista los 2–4 documentos o episodios: autor, título, versión, ubicación y recortes. Explica por qué los elegiste y cómo responden a la pregunta. Los 6–10 segmentos se seleccionan en total de ese conjunto, no de cada documento ni de cada ficha.',5]],
  [['method','Método y contexto documentado','Explica qué enfoque eliges y por qué responde a la pregunta. Define la unidad de análisis —qué cuenta como segmento— y las categorías que aplicarás. Incluye los datos contextuales pertinentes con sus fuentes y localizadores; distingue información comprobada, hipótesis y datos pendientes.',7]],
  [['argument','Desarrollo del análisis','Redacta el análisis de los 6–10 segmentos: presenta la observación localizable, justifica la categoría y el contexto, y explica la relación con tu pregunta. Relaciona regularidades, diferencias, una explicación alternativa y un contraejemplo o límite. Consulta las fichas y selecciona lo pertinente; insertar una cita no escribe el razonamiento por ti. Pregunta, corpus, método y conclusión tienen sus campos propios.',16],['credits','Referencias y atribuciones','Identifica los documentos del corpus y las fuentes teóricas o contextuales que efectivamente usaste: autor, título, fecha, edición o versión y enlace cuando exista. Atribuye un capítulo a su autor. Señala las adaptaciones propias y el uso de herramientas; no agregues toda la biblioteca si no la utilizaste.',7]],
  [['revision','Conclusión revisada y límites','Responde a la pregunta con el análisis realizado. Indica qué puedes afirmar sobre ese corpus y qué no permite generalizar. Incorpora las objeciones de la revisión sin repetir todo el desarrollo.',6],['revisionReason','Registro de cambios','Explica qué afirmación cambiaste o mantuviste, qué evidencia u objeción motivó la decisión y cómo quedó. Conserva un respaldo antes de reemplazar un borrador si quieres mantenerlo completo.',5],['mediation','Actividad de enseñanza','Prepara una microconsigna completa de 5 minutos para probarla en tríos: destinatarios y problema; segmento breve y materiales accesibles; dos o tres pasos; resultado esperado; criterio de revisión. Registra qué dificultad apareció, qué aportaron lector y observador y qué ajustaste. Puedes explicar cómo ampliarla a una clase mayor; la prueba breve no demuestra efectos generales. No exijas repetir tu conclusión como única respuesta.',8],['defense','Guion de defensa','Prepara notas para explicar la pregunta, selección del corpus, enfoque, una evidencia decisiva, una objeción y el límite de la conclusión. Ten a mano los localizadores. La duración y organización de la exposición se indican en clase; este guion no se incorpora al cuerpo del PDF.',5],['selfAssessment','Autoevaluación','Abre la rúbrica y comenta cada dimensión con un ejemplo localizable en tu informe. Señala un logro y una mejora pendiente; no basta poner un porcentaje. Se incluye en el PDF solo si marcas «Autoevaluación» al preparar la entrega.',6]]
 ];
 const notes=state.notes.proyecto||{};
 return `<div class="page-heading"><h1>Expediente final</h1>${origin?`<div class="actions">${link(`#semana/${origin.week}/${origin.encounter}`,`Volver al encuentro: ${esc(origin.title)}`,true)}</div>`:''}<p class="lead">Una pregunta delimitada. Un corpus pequeño. Un análisis que otro lector pueda reconstruir y discutir.</p><p>Informe de 1800–2200 palabras, excluidos anexos y referencias; 2–4 documentos o episodios y 6–10 segmentos localizables en total.</p><p>Los cuatro hitos son avances del mismo expediente, no cuatro informes independientes. Empieza con pregunta y corpus; añade método en la semana 8, desarrollo en la 12 y revisión, enseñanza y defensa en las 15–16. Puedes volver a cualquier campo para ajustar lo anterior.</p><p class="caption">El corpus del expediente puede retomar materiales de las fichas. Selecciona solo los que respondan a su pregunta; no necesitas incorporar todos los ejercicios ni todos los documentos usados en clase. Las notas se guardan al escribir.</p></div>
 <section class="milestones"><h2>Cuatro hitos de trabajo</h2><div class="milestone-links">${milestones.map((m,i)=>button('focus-field',`${i+1} · ${esc(m.title)}`,`data-target="proyecto-${m.fields[0]}"`)).join('')}</div></section>
 <div class="writing-desk project-desk"><section><h2>Construir el informe</h2>${groups.map((fields,i)=>`<details class="project-section" ${i===0||fields.some(([f])=>notes[f]?.trim())?'open':''}><summary>Hito ${i+1} · ${esc(milestones[i].title)} · Semana ${i===3?'15–16':milestones[i].week}</summary><div class="stage-content"><p>${esc(milestones[i].description)}</p>${fields.map(([name,label,help,rows])=>field(state,'proyecto',name,label,help,rows,editable)+(name==='argument'?'<p class="caption" data-word-count="proyecto-argument"></p>':'')).join('')}</div></details>`).join('')}
 <p class="caption" data-report-word-count></p><p class="caption">El contador suma los textos del cuerpo del PDF: pregunta, corpus, método, desarrollo, conclusión, registro de cambios y actividad de enseñanza. Excluye portada, referencias, anexos, guion y autoevaluación. El número orienta la extensión; no evalúa la calidad.</p><p class="caption">Las fichas sirven para consultar y seleccionar evidencia; no se pegan automáticamente como informe. Elige los anexos pertinentes al preparar la entrega.</p><div class="actions">${button('delivery','Preparar mi entrega','',true)}${button('json','Guardar respaldo JSON')}</div><p class="caption">La página no envía el trabajo al docente. Prepara la vista previa, comprueba sus anexos y guarda el PDF desde la impresión del navegador. Entrégalo por el canal indicado en clase; conserva el JSON para continuar editando.</p></section>
 <aside class="desk-evidence"><h2>Consultar mis materiales</h2><div class="desk-tabs" role="tablist" aria-label="Materiales del expediente"><button role="tab" aria-selected="true" aria-controls="project-evidence" id="tab-evidence" data-desk-tab="evidence">Evidencias</button><button role="tab" aria-selected="false" aria-controls="project-notes" id="tab-notes" tabindex="-1" data-desk-tab="notes">Fichas</button><button role="tab" aria-selected="false" aria-controls="project-map" id="tab-map" tabindex="-1" data-desk-tab="map">Relaciones</button></div>
 <div id="project-evidence" role="tabpanel" aria-labelledby="tab-evidence">${evidenceList(state,null,false,true)}${state.evidence.length?'':link('#unidad/1/analizar','Registrar mi primera evidencia · Unidad 1')}</div>
 <div id="project-notes" role="tabpanel" aria-labelledby="tab-notes" hidden>${units.map(u=>{const n=state.notes[`ficha-${u.id}`]||{};return `<details id="project-ficha-${u.id}"><summary>Ficha ${u.id} · ${esc(u.title)} · ${status(state,`ficha-${u.id}`)}</summary>${['question','argument','revision','revisionReason'].filter(f=>n[f]?.trim()).map(f=>`<h3>${esc(fieldLabels[f])}</h3><p class="preserve">${esc(n[f])}</p>`).join('')||'<p>La ficha todavía no tiene texto.</p>'}${link(`#unidad/${u.id}/argumentar`,'Abrir ficha')}</details>`;}).join('')}</div>
 <div id="project-map" role="tabpanel" aria-labelledby="tab-map" hidden>${relationDiagram(state.relations)}</div><details class="rubric" id="project-rubric" tabindex="-1"><summary>Rúbrica del informe</summary>${rubric.map(([title,weight,text])=>`<h3>${title} · ${weight}%</h3><p>${text}</p>`).join('')}<p class="caption">Estos porcentajes son dimensiones del informe, distintos de los pesos institucionales del curso.</p></details></aside></div>`;
}

function relationForm(editable){return `<form id="relation-form"><h2>Relacionar documentos o voces</h2><p class="caption">Este registro es un apoyo para comparar documentos o voces, especialmente en la ficha 5. Escribe en «Desde» la pieza de partida y en «Hacia» la que comparas o deriva de ella. Elige «Relación documentada» si una fuente acredita el vínculo; «Propuesta de análisis» si planteas una hipótesis o una adaptación propia. Explica abajo la relación antes de añadirla; el gráfico solo representa lo que registras.</p><div class="form-row"><div class="field"><label for="r-from">Desde: documento o voz</label><input id="r-from" name="from" required maxlength="1000" ${editable?'':'disabled'}></div><div class="field"><label for="r-to">Hacia: documento o voz</label><input id="r-to" name="to" required maxlength="1000" ${editable?'':'disabled'}></div></div><div class="form-row"><div class="field"><label for="r-type">Estado del vínculo</label><select id="r-type" name="type" ${editable?'':'disabled'}><option value="propuesta">Propuesta de análisis</option><option value="documentada">Relación documentada</option></select></div><div class="field"><label for="r-medium">Medio o soporte (opcional)</label><p class="field-help">Indica las materialidades pertinentes a la comparación y a cuál pieza corresponden. Si no intervienen en tu pregunta, deja el campo vacío.</p><input id="r-medium" name="medium" maxlength="1000" ${editable?'':'disabled'}></div></div><div class="field"><label for="r-mediator">Quién transforma o hace circular (opcional)</label><p class="field-help">Identifica al responsable del vínculo si lo conoces; en una adaptación propia puedes escribir «elaboración propia». No atribuyas esa acción sin datos.</p><input id="r-mediator" name="mediator" maxlength="1000" ${editable?'':'disabled'}></div><div class="field"><label for="r-evidence">Descripción del vínculo y fuente</label><p class="field-help">Documentado: describe qué une las piezas y cita la fuente con localizador. Propuesto: explica tu hipótesis o qué transformaste en el experimento, identifica las piezas y señala qué falta comprobar.</p><textarea id="r-evidence" name="evidence" required rows="3" maxlength="10000" ${editable?'':'disabled'}></textarea></div><div class="actions"><button class="button" type="submit" ${editable?'':'disabled'}>Añadir relación${icon}</button>${button('cancel-relation','Vaciar preparación')}</div><p class="caption">Añadir relación la incorpora a la lista y al gráfico. Vaciar preparación borra este formulario; no elimina las relaciones registradas. El argumento sobre el vínculo se escribe en la ficha o el expediente.</p><p class="field-error" id="relation-error" role="alert"></p></form>`;}
function notebookDiagnosis(state,editable){const n=state.notes.apertura||{};return `<section class="notebook-diagnosis"><h2>Mi diagnóstico inicial · Semana 1</h2><p>Estos son los mismos campos de los encuentros 1 y 2. Lo que escribes aquí aparece también en la clase correspondiente; no necesitas copiarlo. El diagnóstico no tiene calificación y se conserva separado de las seis fichas.</p>${field(state,'apertura','argument','Mi lectura inicial','Observación y palabras que la respaldan; dos hipótesis; información necesaria para contrastarlas.',5,editable)}<details ${n.revision?.trim()||n.revisionReason?.trim()?'open':''}><summary>Revisión del diagnóstico · Encuentro 2</summary><p>Completa esta parte después de contrastar los contextos en el segundo encuentro.</p>${field(state,'apertura','revision','Mi lectura después del contraste','Justifica lo que mantienes, corriges o restringes.',4,editable)}${field(state,'apertura','revisionReason','Qué cambió y qué evidencia falta','Nombra el dato o la objeción que afecta tu lectura.',3,editable)}</details><div class="actions">${link('#semana/1/1','Volver a la lectura inicial')}${link('#semana/1/2','Abrir el contraste')}</div></section>`;}
function notebook(state,editable){return `<div class="page-heading"><h1>Mi cuaderno</h1><p class="lead">Fichas, evidencias y versiones de trabajo en este navegador.</p><p class="caption">Las notas se guardan automáticamente aquí. El JSON permite recuperar la edición; el PDF es la entrega por el canal que indique el docente. Guarda el respaldo fuera de un equipo compartido.</p></div><div class="notebook-tools actions">${button('json','Guardar respaldo JSON','',true)}${button('import','Recuperar respaldo')}${button('markdown','Exportar texto')}${button('delivery','Preparar entrega PDF')}${button('lock','Ocultar mi cuaderno')}</div>${notebookDiagnosis(state,editable)}<details class="personal-notes"><summary>Notas personales y acuerdos</summary><p class="caption">Estas notas son opcionales. Se conservan también los textos que hayas escrito en versiones anteriores del cuaderno.</p>${field(state,'apertura','expectations','Experiencias, expectativas y pregunta inicial','Sin calificación. Puedes volver a esta nota al final del curso.',4,editable)}${field(state,'apertura','agreements','Acuerdos que quiero conservar','La nota personal no sustituye un acta colectiva.',3,editable)}${field(state,'apertura','reflection','Reflexión sobre mi recorrido','Qué puedo explicar mejor y qué necesito seguir investigando.',3,editable)}</details><section><h2>Mis seis fichas</h2><p>Cada enlace abre «Escribir argumento» de esa unidad. Las evidencias y revisiones se consultan en sus otros pasos; todos pertenecen a la misma ficha.</p><div class="notebook-index">${units.map(u=>`<a href="#unidad/${u.id}/argumentar"><strong>Ficha ${u.id} · ${esc(u.title)}</strong>${status(state,`ficha-${u.id}`)}</a>`).join('')}</div></section><section><h2>Registro de evidencias</h2><p>Esta lista reúne las entradas de las seis unidades; no es una actividad nueva. Usa «Editar evidencia» para completar un registro o vuelve a «Registrar evidencias» en su unidad para añadir otro.</p>${evidenceList(state,null,editable)}</section><section class="relationships"><h2>Relaciones con evidencia</h2>${relationDiagram(state.relations)}<div class="relation-list">${state.relations.map(r=>`<article><h3>${esc(r.from)} → ${esc(r.to)}</h3><p class="caption">${esc(r.type)}${r.mediator?' · '+esc(r.mediator):''}${r.medium?' · '+esc(r.medium):''}</p><p class="preserve">${esc(r.evidence)}</p>${editable?button('delete-relation','Eliminar relación',`data-id="${esc(r.id)}"`):''}</article>`).join('')}</div>${relationForm(editable)}</section><details class="storage-help"><summary>Guardado, consulta y equipo compartido</summary><p>Las notas se guardan localmente, en este navegador y dirección de la aplicación. No se envían al docente ni se sincronizan entre dispositivos. El respaldo JSON es la copia recuperable.</p><p>Si hay un cuaderno previo, sus notas se mantienen ocultas hasta elegir continuarlo. Después de 20 minutos de inactividad se oculta el trabajo. Este control no es autenticación o cifrado.</p><p>Cuando otra pestaña cambia el cuaderno durante una edición, se detiene el guardado y se ofrece una copia en memoria; no se sobrescribe el trabajo silenciosamente. El modo consulta permite recorrer el curso sin escribir notas.</p></details><section class="delete-zone"><h2>Limpiar este navegador</h2><p>Antes de salir de un equipo compartido, conserva tu JSON. El borrado requiere confirmación y se comunica a las otras pestañas.</p>${button('clear','Borrar el cuaderno de este navegador')}</section>`;}
export const agencyHtml=()=>`<section class="agency-material"><h2>Tres versiones didácticas</h2><p class="caption">Ejemplos inventados para el taller. No son citas de una noticia ni describen un hecho real de la UCE.</p><div class="agency-versions"><p><span>A</span>La dirección suspendió las becas de cuarenta estudiantes.</p><p><span>B</span>Se suspendieron las becas de cuarenta estudiantes.</p><p><span>C</span>La suspensión de las becas afectó a cuarenta estudiantes.</p></div><details><summary>Contextos de contraste, para la segunda parte</summary><p><strong>Contexto 1, construido:</strong> una nota breve ya identificó al órgano que tomó la decisión. Examina si B recupera esa información o la vuelve difícil de reconocer.</p><p><strong>Contexto 2, construido:</strong> un comunicado omite sistemáticamente a ese órgano. Explica qué dato adicional permitiría sostener o refutar una estrategia de opacidad.</p></details></section>`;
function sessionPage(route,state,editable){
 const s=getSession(route.week,route.encounter),work=sessionWork(s),diagnosis=s.week===1,initialOnly=diagnosis&&s.encounter===1;
 const sequence=diagnosis?sessions.filter(item=>item.week===1):unitSequence(s.unit),position=sequence.findIndex(item=>item.id===s.id),previous=sequence[position-1],next=sequence[position+1];
 const projectField=work.field||(s.week===14?'argument':projectFieldForWeek(s.week));
 const stepActions={observar:'Leer la guía',analizar:'Registrar evidencias',argumentar:'Escribir el argumento',revisar:'Escribir la revisión'};
 const workLink=work.step==='assessment'?link(work.href,'Consultar la ficha 3 para preparar la evaluación'):link(work.href,diagnosis?'Ver mi diagnóstico en el cuaderno':work.key==='proyecto'?'Escribir en mi expediente':`${s.week===4&&s.encounter===1?'Guardar la pregunta':stepActions[work.step]} · Ficha ${work.unit.id}`,true,work.field?`data-project-field="${work.field}"`:'');
 const connection=`<section class="session-connection"><h2>En qué trabajo se integra esta clase</h2><p><strong>${esc(work.label)}</strong></p><p>${esc(work.explanation)}</p><p><strong>Avance de esta semana:</strong> ${esc(work.path.advance)}</p>${work.step==='assessment'?`<div class="actions">${link(work.href,'Consultar la ficha 3 como preparación')}</div>`:!diagnosis&&work.key!=='proyecto'?`<div class="actions">${link(`#unidad/${s.unit}/observar`,'Leer la guía')}${link(`#unidad/${s.unit}/analizar`,'Registrar evidencias')}${link(`#unidad/${s.unit}/argumentar`,`Consultar mi ficha ${s.unit}`)}</div>`:''}</section>`;
 const record=diagnosis?`<section class="diagnosis-record"><h2>Mi registro del diagnóstico</h2><p>${initialOnly?'Usa este campo para tomar notas durante el taller. Al terminar, ordénalas en un párrafo con una observación, dos hipótesis y el dato que falta. No abras los contextos todavía: contrastarás esta lectura en el encuentro 2.':'Retoma la lectura inicial guardada en el encuentro 1. Ahora abre «Contextos de contraste» y examina qué hipótesis gana o pierde apoyo en cada contexto. En los campos siguientes, explica qué mantienes o corriges y por qué.'} Este diagnóstico no tiene calificación.</p>${field(state,'apertura','argument','Mi lectura inicial','Observación y palabras que la respaldan; dos hipótesis; información necesaria para contrastarlas.',5,editable)}${initialOnly?'':field(state,'apertura','revision','Mi lectura después del contraste','Examina los dos contextos construidos; justifica lo que mantienes o restringes.',4,editable)+field(state,'apertura','revisionReason','Qué cambió y qué evidencia falta','Nombra el dato o la objeción que afecta tu lectura.',3,editable)}<p class="caption">Se guarda automáticamente como diagnóstico de apertura, separado de la ficha oral.</p></section>`:'';
 return `<div class="page-heading"><h1>${esc(s.title)}</h1><p class="lead">${esc(s.question)}</p><p class="caption">Semana ${s.week} · Encuentro ${s.encounter} · ${s.duration} minutos · Unidad ${s.unit}</p><div class="actions">${button('class','Proyectar este encuentro',`data-week="${s.week}" data-encounter="${s.encounter}"`,true)}${link(`#unidad/${s.unit}/situar`,'Abrir la unidad')}</div></div>
 ${connection}<div class="session-layout"><section><h2>Antes de este encuentro</h2><p>${esc(s.preparation)}</p><h2>Trabajar en clase</h2><ol class="agenda">${s.agenda.map(([duration,title,text])=>`<li><span class="agenda-time">${duration} min</span><div><h3>${esc(title)}</h3><p>${esc(text)}</p></div></li>`).join('')}</ol><h2>Qué conservar al cerrar</h2><p>${esc(s.product)}</p>${record}<div class="actions">${workLink}${s.defensePlan&&work.field!=='defense'?link('#proyecto','Consultar mi guion de defensa',false,'data-project-field="defense"'):''}${projectField&&!work.field?link('#proyecto',work.path.milestone?`Continuar el hito ${work.path.milestone} del expediente`:'Actualizar el desarrollo del expediente',false,`data-project-field="${projectField}"`):''}</div></section>
 <aside class="session-document">${sessionMaterialHtml(s)}</aside></div>
 <nav class="session-next actions" aria-label="Continuar encuentros">${previous?link(`#semana/${previous.week}/${previous.encounter}`,'Volver al encuentro anterior'):''}${link(`#unidad/${s.unit}/situar`,'Ver el orden de la unidad')}${next?link(`#semana/${next.week}/${next.encounter}`,`Siguiente encuentro: ${esc(next.title)}`,true):diagnosis?link('#unidad/1/situar','Comenzar la unidad oral',true):s.unit<6?link(`#unidad/${s.unit+1}/situar`,`Continuar con la unidad ${s.unit+1}`,true):link('#proyecto','Preparar la entrega final',true)}</nav>`;
}

function sessionMaterialHtml(s){const m=sessionMaterials(s);return `${m.corpus.length?`<h2>${s.week===1?'Material central del encuentro':'Documento de análisis'}</h2>${m.corpus.map(id=>id==='agencia'?agencyHtml():resourceCard(resourceById[id],true)).join('')}`:`<h2>Documento de análisis</h2>`}${m.note?`<p class="caption">${esc(m.note)}</p>`:''}${m.readings.length?`<h2>Guía y lecturas de apoyo</h2><p class="caption">Ayudan a analizar el documento. No se añaden como otros corpus ni como otra entrega.</p>${m.readings.map(id=>resourceCard(resourceById[id],true)).join('')}`:''}`;}

export function glossaryPage(){return `<div class="page-heading"><h1>Glosario situado</h1><p class="lead">Una formulación, una operación y un límite. Los conceptos ayudan a investigar; su nombre no reemplaza la evidencia.</p></div><div class="glossary-list">${Object.entries(glossary).map(([id,g])=>`<button type="button" data-concept="${id}"><strong>${esc(g.term)}</strong><span>${esc(g.author)}</span>${icon}</button>`).join('')}</div>`;}
export function conceptHtml(id){const g=glossary[id];return `<div class="dialog-heading"><h2 id="concept-title">${esc(g.term)}</h2>${button('close-dialog','Cerrar','autofocus')}</div><p class="caption">${esc(g.author)}</p><h3>Formulación</h3><p>${esc(g.definition)}</p><h3>Operación de análisis</h3><p>${esc(g.operation)}</p><h3>Ejemplo para comprender la operación</h3><p class="caption">Es una ilustración didáctica; no añade una entrega a la actividad de la unidad.</p><p>${esc(examples[id])}</p><h3>Límite o precaución</h3><p>${esc(g.limit)}</p>`;}
export function renderPage(route,state,editable,origin=null){if(route.page==='unidad')return unitPage(route,state,editable,origin);if(route.page==='semana')return sessionPage(route,state,editable);if(route.page==='biblioteca')return library();if(route.page==='proyecto')return project(state,editable,origin);if(route.page==='cuaderno')return notebook(state,editable);if(route.page==='glosario')return glossaryPage();return home(state);}
export function renderClass(s,index=0){
 const slides=classSlides(s),position=Math.max(0,Math.min(slides.length-1,index)),slide=slides[position],step=s.agenda[slide.block];
 const kinds={concept:'Concepto',example:'Ejemplo comentado',work:/Pausa/.test(slide.title)?'Pausa':/Cierre|Conservar|Cerrar/.test(slide.title)?'Cierre':'Trabajo en clase'};
 const firstDiagnostic=s.week===1&&s.encounter===1&&slide.block===0;
 const task=`<p class="class-question">${esc(s.question)}</p><p class="class-task">${esc(slide.task||'')}</p>`;
 const material=s.resource==='agencia'&&(/Taller/.test(step[1])||firstDiagnostic)?agencyHtml():sessionMaterials(s).corpus.includes('drexler')?`<p class="class-material"><a href="${resourceById.drexler.url}" target="_blank" rel="noopener noreferrer">Abrir la charla y su transcripción española${icon}</a><span>Tramo de análisis: 00:39–01:47. El visionado completo se hace en la primera clase oral.</span></p>`:'';
 let content;
 if(slide.kind==='concept')content=`<p class="class-explanation">${esc(slide.explanation)}</p><ul class="class-points">${slide.points.map(point=>`<li>${esc(point)}</li>`).join('')}</ul><div class="class-discussion"><span>Para discutir</span><p>${esc(slide.prompt)}</p></div>`;
 else if(slide.kind==='example')content=`<p class="caption">Ilustración didáctica elaborada para esta explicación. No es una cita del corpus ni una entrega adicional.</p><blockquote class="class-example">${esc(slide.example)}</blockquote><p class="class-reading">${esc(slide.reading)}</p><div class="class-discussion"><span>Volver al problema</span><p>${esc(slide.prompt)}</p></div>`;
 else content=firstDiagnostic?`<div class="class-work"><div>${task}</div>${material}</div>`:task+material;
 const deepen=slide.kind==='concept'&&lessons[s.unit]?.[slide.lesson];
 const plainLesson=deepen?deepen[1].replace(/\[\[([a-z-]+)(?:\|([^\]]+))?\]\]/g,(_,id,label)=>label||glossary[id]?.term||id):'';
 const source=slide.source&&resourceById[slide.source];
 const sources=(source?resourceCard(source,true):sessionMaterialHtml(s)).replace(/(<a class="source-link" href=")(#[^"]+)(")/g,`$1$2$3 target="_blank" rel="noopener noreferrer"`);
 const next=s.encounter===1?getSession(s.week,2):getSession(s.week+1,1);
 const nextButton=position<slides.length-1?button('class-next','Pantalla siguiente','',true):next?button('class-next-encounter','Siguiente encuentro','',true):button('class-next','Encuentro completado','disabled',true);
 return `<div class="class-controls"><div><label for="class-week">Semana</label><select id="class-week">${Array.from({length:16},(_,i)=>`<option value="${i+1}" ${s.week===i+1?'selected':''}>${i+1}</option>`).join('')}</select></div><div><label for="class-encounter">Encuentro</label><select id="class-encounter"><option value="1" ${s.encounter===1?'selected':''}>1 · 60 minutos</option><option value="2" ${s.encounter===2?'selected':''}>2 · 120 minutos</option></select></div><div class="class-screen-select"><label for="class-screen">Ir a una pantalla</label><select id="class-screen">${slides.map((item,i)=>`<option value="${i}" ${i===position?'selected':''}>${i+1}. ${item.kind==='concept'?'Concepto':item.kind==='example'?'Ejemplo':'Trabajo'} · ${esc(item.title)}</option>`).join('')}</select></div>${button('close-dialog','Cerrar proyección')}</div><section class="class-slide" data-slide-kind="${slide.kind}" aria-labelledby="class-title"><div class="class-progress"><span>${kinds[slide.kind]}</span><p>Semana ${s.week} · Encuentro ${s.encounter} · Pantalla ${position+1}/${slides.length}</p></div><h1 id="class-title" tabindex="-1">${esc(slide.title)}</h1>${content}${deepen?`<details class="class-deepen"><summary>Ampliar la explicación</summary><h2>${esc(deepen[0])}</h2><p>${esc(plainLesson)}</p></details>`:''}<details class="class-resource"><summary>Fuentes y material de consulta</summary>${sources}</details></section><div class="class-timing"><strong>Bloque ${slide.block+1}/${s.agenda.length}: ${esc(step[1])} · ${step[0]} min en total</strong><span>Las pantallas de este bloque comparten el tiempo previsto.</span></div><div class="class-navigation">${button('class-prev','Pantalla anterior',position===0?'disabled':'')}${nextButton}</div>`;
}
